    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def regions(n, separators):
        spans, start = [], 0
        for i in separators:
            if start < i:
                spans.append((start, i))
            start = i + 1
        if start < n:
            spans.append((start, n))
        return spans

    rows, cols = regions(h, sep_rows), regions(w, sep_cols)
    if len(rows) > 1 and len(cols) <= 1:
        panels = [(a, b, 0, w) for a, b in rows]
    elif len(cols) > 1 and len(rows) <= 1:
        panels = [(0, h, a, b) for a, b in cols]
    elif len(rows) > 1:
        panels = [(a, b, 0, w) for a, b in rows]
    elif len(cols) > 1:
        panels = [(0, h, a, b) for a, b in cols]
    else:
        return [row[:] for row in grid]

    def non_background_count(panel):
        r0, r1, c0, c1 = panel
        return sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))

    source = max(panels, key=non_background_count)
